import sys
sys.setrecursionlimit(300000)

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))

    if n < 2:
        print("Impossible")
        return

    a = []
    for _ in range(n):
        a.append(int(next(iterator)))

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                stack.append(v)

    subtree_sum = [0] * (n + 1)
    for i in range(n - 1, -1, -1):
        u = order[i]
        s = a[u - 1]
        for v in adj[u]:
            if v != parent[u]:
                s += subtree_sum[v]
        subtree_sum[u] = s

    best_child_max = [-float('inf')] * (n + 1)
    best_child_second_max = [-float('inf')] * (n + 1)

    for i in range(n - 1, -1, -1)[::-1]:
        u = order[i]
        children = [v for v in adj[u] if v != parent[u]]

        if not children:
            continue

        max1 = -float('inf')
        max2 = -float('inf')

        for v in children:
            val = subtree_sum[v]
            if val > max1:
                max2 = max1
                max1 = val
            elif val > max2:
                max2 = val

        best_child_max[u] = max1
        best_child_second_max[u] = max2

    global_max = -float('inf')

    for u in range(1, n + 1):
        children = [v for v in adj[u] if v != 0]
        if len(children) >= 2:
            vals = [subtree_sum[v] for v in children]
            vals.sort(reverse=True)
            current_sum = vals[0] + vals[1]
            if current_sum > global_max:
                global_max = current_sum

        if parent[u] != 0:
            p = parent[u]
            val_u = subtree_sum[u]
            other_children = [v for v in adj[p] if v != parent[p] and v != u]

            if not other_children:
                if best_child_second_max[p] != -float('inf'):
                    candidate = val_u + best_child_second_max[p]
                    if candidate > global_max:
                        global_max = candidate
            else:
                best_others = -float('inf')
                for v in other_children:
                    if subtree_sum[v] > best_others:
                        best_others = subtree_sum[v]

                if best_others != -float('inf'):
                    candidate = val_u + best_others
                    if candidate > global_max:
                        global_max = candidate

    if global_max == -float('inf'):
        print("Impossible")
    else:
        print(global_max)

if __name__ == "__main__":
    main()
